//! Dwell's characters (docs/CHARACTERS.md, ADR 0041; Phase 40 C1): the player's full body and
//! first-person arms from `shared/characters/characters.json`.
//!
//! - The tables (`characters.gen.rs`) are generated by `shared/characters/gen.mjs` from the same data
//!   the Character Lab draws: every look composed into parts on bones (rig.mjs `compose`), items,
//!   clips and the shared materials they paint with. Code names characters, looks, items and clip
//!   roles by string (`"player"`, `"wanderer"`, `"walk"`), never by index constant.
//! - `mesh`: each part a rigid mesh on its bone (no skinning, §9.1), one mesh per look and view.
//! - `anim`: sampling, layering and cross-fading clips (rig.mjs's twin), and the bones' transforms.
//! - `animator`: which clip plays, from the controller state a remote snapshot carries (§6), with the
//!   cross-fades, one-shots, swings and the head following the look's pitch; and the arms' twin.

pub mod anim;
pub mod animator;
pub mod math;
pub mod mesh;
mod types;

pub use types::*;

#[rustfmt::skip]
#[allow(clippy::all)]
mod tables {
    include!("characters.gen.rs");
}

/// A second set of tables for tests: the build's data plus `shared/characters/fixtures/*.json`
/// (a pauldron added by data alone), generated by the same `gen.mjs`. Never used by a build.
#[cfg(test)]
#[rustfmt::skip]
#[allow(clippy::all, dead_code)]
pub(crate) mod fixture {
    include!("fixture.gen.rs");
}

/// One generated set of tables.
#[derive(Clone, Copy, Debug)]
pub struct Tables {
    pub characters: &'static [Character],
    pub clips: &'static [Clip],
    pub materials: &'static [Material],
    /// Brush tiles, `TILE` × `TILE` bytes each.
    pub tiles: &'static [u8],
}

/// The build's tables.
pub static TABLES: Tables = Tables {
    characters: tables::CHARACTERS,
    clips: tables::CLIPS,
    materials: tables::MATERIALS,
    tiles: tables::TILES,
};

#[cfg(test)]
pub(crate) static FIXTURE: Tables = Tables {
    characters: fixture::CHARACTERS,
    clips: fixture::CLIPS,
    materials: fixture::MATERIALS,
    tiles: fixture::TILES,
};

/// Texels per brush tile edge.
pub const TILE: usize = tables::TILE;

/// The player's character and the look everyone wears until looks are chosen (CHARACTERS.md §9.4).
pub const PLAYER: &str = "player";
pub const DEFAULT_LOOK: &str = "wanderer";

impl Tables {
    pub fn character(&self, id: &str) -> Option<&'static Character> {
        self.characters.iter().find(|c| c.id == id)
    }
    pub fn clip(&self, index: usize) -> &'static Clip {
        &self.clips[index]
    }
    /// The number of brush tiles.
    pub fn tile_count(&self) -> usize {
        self.tiles.len() / (TILE * TILE)
    }
}

/// The player character of the build's tables.
pub fn player() -> &'static Character {
    TABLES.character(PLAYER).expect("the data has the player")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_hold_the_player_with_its_looks_items_and_clips_by_name() {
        let p = player();
        assert_eq!(p.name, "dwell:player");
        assert!(p.look(DEFAULT_LOOK).is_some());
        assert!(p.item("block").is_some() && p.item("brush").is_some());
        for role in [
            "idle", "walk", "sprint", "slide", "jump", "fall", "land", "hold", "break",
        ] {
            let c = TABLES.clip(p.clip(role).unwrap_or_else(|| panic!("{role}")));
            assert_eq!(c.space, Space::Body);
        }
        let fp = p.first_person.expect("first person");
        assert_eq!(fp.bones.len(), 3);
        assert!(p.arms_clip("walk").is_some());
        assert_eq!(TABLES.tile_count() * TILE * TILE, TABLES.tiles.len());
        // Every tile a material names is there.
        for m in TABLES.materials {
            assert!(m.tile < TABLES.tile_count() as i32, "{}", m.name);
        }
    }
}
